    fbBuilder.addOffset(13, SOURCE_NAMEOffset);
    fbBuilder.addOffset(14, BATCH_IDOffset);
    fbBuilder.addOffset(15, PRODUCER_PEER_IDOffset);
    fbBuilder.addOffset(16, ORIGIN_IDOffset);
    fbBuilder.addInt64(17, _FROM_EPOCH_MS);
